#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MOBILE="$(cd "$HERE/.." && pwd)"
REPO="$(cd "$MOBILE/.." && pwd)"
KEYDIR="$HOME/.vetmock-android"
KEYSTORE="$KEYDIR/upload.jks"
mkdir -p "$KEYDIR"
ENV_FILE="$KEYDIR/play.env"   # public values only: links and certificate fingerprints, never a password
# shellcheck source=env.sh
. "$HERE/env.sh"
KEYTOOL="$JAVA_HOME/bin/keytool"
AAB="$MOBILE/android/app/build/outputs/bundle/release/app-release.aab"

fingerprint() {  # fingerprint SHA256|SHA1 of the upload key
  "$KEYTOOL" -list -v -keystore "$KEYSTORE" -alias upload -storepass:env VETMOCK_UPLOAD_STORE_PASSWORD 2>/dev/null |
    sed -n "s/^[[:space:]]*$1:[[:space:]]*//p" | head -n1
}
take_lock() {    # one heavy job at a time on this laptop (C:/dev/HEAVY-GATE-RULE.md)
  until (set -o noclobber; printf 'vm-android-wizard %s\n' "$(date -Iseconds)" > C:/dev/heavy-gate.lock) 2>/dev/null; do
    note "another heavy job holds C:/dev/heavy-gate.lock; trying again in a minute"; sleep 60
  done
  trap 'rm -f C:/dev/heavy-gate.lock' EXIT
}
release_lock() { rm -f C:/dev/heavy-gate.lock; trap - EXIT; }

banner "VetMock Android: from upload key to internal testing"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Your upload key"
say "Google Play keeps the key that signs the app (Play App Signing). You keep an upload key,"
say "which proves an upload is yours. It lives in $KEYSTORE, never in the repo or a chat."
if [[ -f "$KEYSTORE" ]]; then
  note "An upload key already exists; keeping it."
else
  step "keytool asks for a password twice. Choose a long one and keep it in your password manager."
  step "If it is ever lost, Play Console can reset the upload key, but that takes days."
  pause "Press Enter to create the key"
  "$KEYTOOL" -genkeypair -keystore "$KEYSTORE" -alias upload -keyalg RSA -keysize 4096 -validity 10000 \
    -dname "CN=VetMock, O=VetMock, L=Bangkok, C=TH"
fi
ask_secret VETMOCK_UPLOAD_STORE_PASSWORD "Type the upload key password (for this run only, never saved):"
export VETMOCK_UPLOAD_STORE_PASSWORD
UPLOAD_SHA256="$(fingerprint SHA256)"
UPLOAD_SHA1="$(fingerprint SHA1)"
if [[ -z "$UPLOAD_SHA256" ]]; then warn "That password does not open $KEYSTORE. Run the wizard again."; exit 1; fi
write_env UPLOAD_SHA256 "$UPLOAD_SHA256"
write_env UPLOAD_SHA1 "$UPLOAD_SHA1"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Build the signed app bundle"
say "This downloads the exact build vetmock.com serves, puts it in the app and signs the bundle."
say "It takes the machine's heavy-job lock, so it may wait for another build first."
pause "Press Enter to build"
take_lock
( cd "$MOBILE" && { [[ -d node_modules ]] || npm ci --no-audit --no-fund; } && node scripts/fetch-bundle.mjs && npx cap sync android )
VETMOCK_VERSION_CODE="$(date +%y%m%d%H)"
( cd "$MOBILE/android" &&
  VETMOCK_UPLOAD_KEYSTORE="$KEYSTORE" VETMOCK_UPLOAD_KEY_ALIAS=upload VETMOCK_VERSION_CODE="$VETMOCK_VERSION_CODE" \
  ./gradlew --no-daemon bundleRelease )
release_lock
if [[ ! -f "$AAB" ]]; then warn "No bundle was produced; the Gradle output above says why."; exit 1; fi
say "Bundle: $AAB ($(du -h "$AAB" | cut -f1), version code $VETMOCK_VERSION_CODE)"
explorer.exe "$(cygpath -w "$(dirname "$AAB")")" >/dev/null 2>&1 || true
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Play Console: create the app"
open_url "https://play.google.com/console/developers"
step "All apps, then Create app (top right)."
step "App name: VetMock. Default language: Thai (th). App or game: App. Free or paid: Free."
step "Read and tick the two declarations (Developer Program Policies, US export laws). They are yours to make."
step "Create app."
note "If VetMock is already in the list, open it and skip this stage."
pause "Press Enter when the app's dashboard is open"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Play Console: app content and store listing"
say "Every answer is written out in $MOBILE/store/ and matches what the app does."
step "Policy and programs, App content: work down the list with store/app-content.md"
step "(privacy policy, app access, ads, content rating, target audience, Data safety from store/data-safety.md)."
step "Grow users, Store presence, Main store listing: copy the texts from store/listing-th.md;"
step "upload public/icon-512.png, store/feature-graphic.png and the phone screenshots in store/screenshots/."
explorer.exe "$(cygpath -w "$MOBILE/store")" >/dev/null 2>&1 || true
pause "Press Enter when App content shows no open tasks"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Play Console: internal testing"
step "Test and release, Testing, Internal testing. Testers tab: Create email list, add the testers' Google emails, Save."
step "Releases tab: Create new release. If asked about app signing, keep 'Use Google-generated key'."
step "Upload: $AAB"
step "Release notes: paste store/release-notes-th.txt. Next, then Save and publish (or Start rollout)."
step "Back on the Testers tab, under 'How testers join your test': Copy link."
if confirm "Has the release been rolled out to internal testing?"; then
  ask INTERNAL_TEST_URL "Paste the testers' join link:"
  write_env INTERNAL_TEST_URL "$INTERNAL_TEST_URL"
fi

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Play Console: the app signing certificate"
say "vetmock.com links (and sign-in returns) open in the app only once vetmock.com names this certificate."
step "Test and release, App integrity, App signing tab: 'App signing key certificate'."
ask PLAY_SHA256 "Paste its SHA-256 fingerprint:"
ask PLAY_SHA1 "Paste its SHA-1 fingerprint:"
write_env PLAY_SHA256 "$PLAY_SHA256"
write_env PLAY_SHA1 "$PLAY_SHA1"
node "$HERE/assetlinks.mjs" "$REPO/public/.well-known/assetlinks.json" "$PLAY_SHA256" "$UPLOAD_SHA256"
say "Tell Claude: assetlinks พร้อมแล้ว. It opens the pull request that publishes the file."
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: let Android sign in with Google"
say "Android's account sheet works once Google knows the app's package and certificates."
open_url "https://console.cloud.google.com/apis/credentials"
step "Pick the project that holds the VetMock web client (its client ID starts 807323754507)."
step "Create credentials, OAuth client ID, Application type: Android."
step "Name: VetMock Android (Play). Package name: com.vetmock.app. SHA-1: $PLAY_SHA1. Create."
step "Create one more: VetMock Android (upload), same package, SHA-1: $UPLOAD_SHA1."
note "Nothing to copy back: the app asks Google with the existing web client ID."
pause "Press Enter when both Android clients exist"

finish
say "Internal testing link: ${INTERNAL_TEST_URL:-not set yet}"
say "Kept in $ENV_FILE (links and fingerprints only, no password)."
}

run_wizard "$@"; exit
